	box-shadow: 10px 10px #cccccc;
	border: 2px solid #aaa;
	border-radius: 2%;
}

.flex-container-diarios{
	border: 2px solid #aaa;
	border-radius: 10px;
	/* padding: 10px; */
	box-shadow: 10px 10px #cccccc;
	height: 300px;
	background-color:#f9f9f9;
	display: flex;
	flex-direction: column;
	justify-content:start;
	overflow: auto;
}


.div_imagem{
	display: none
  }

.prev, .next{
	position: absolute;
	top: 50%;
	transform: translate(0, -50%);
	font-size: 50px;
	padding: 15px;
	cursor: pointer;
	color: #333232;
	transition: 0.1s;
	user-select: none;
}
.prev:hover, .next:hover{
	color: #00a7ff; /* blue */
}
.next{
	right: 0;
}
.dotsbox{
	width: 100%;
	position: absolute;
	left: 50%;
	transform: translate(-50%);
	bottom: -26px;
	cursor: pointer;
}
.dot{
	display: inline-block;
	width: 5px;
	height: 5px;
	border: 2px solid #141414;
	border-radius: 50%;
	margin: 0 10px;
	cursor: pointer;
}
