function buscarImagens() {
  var sucesso = function (aData) {
    if (!aData) {
      console.warn('Resposta vazia do servidor');
      $(".slider").hide();
      return;
    }

    if (aData.error_message) {
      $("#div_notificacao_norma").messagelight({
        sTitle: "Erro",
        sContent: aData.error_message,
        sType: "error",
        sWidth: "",
        iTime: null,
      });
      return;
    }

    if (!Array.isArray(aData) || aData.length === 0) {
      $(".slider").hide();
      return;
    }

    // imagens (até 5)
    for (let i = 0; i < Math.min(aData.length, 5); i++) {
      const imgEl = document.querySelector("#img" + i);
      if (imgEl && aData[i] && aData[i].img_byte) {
        imgEl.setAttribute("src", "data:image/jpeg;base64," + aData[i].img_byte);
      }
    }

    // títulos e links - usa loop para reduzir repetição
    for (let i = 0; i < 5; i++) {
      const titleEl = document.querySelector("#titulo" + i);
      const linkEl = document.querySelector("#link" + i);
      if (aData[i]) {
        if (titleEl) titleEl.innerHTML = aData[i].nm_titulo || "";
        if (linkEl && aData[i].nm_link) linkEl.setAttribute("href", aData[i].nm_link);
      } else {
        // remove elementos relacionados se não existir dado
        const dot = document.querySelector("#dot" + (i + 1)); // note: seus ids parecem 1..5
        const t = document.querySelector("#t" + i);
        if (dot) dot.remove();
        if (t) t.remove();
        if (titleEl) titleEl.innerHTML = "";
        if (linkEl) linkEl.removeAttribute("href");
      }
    }

    // Inicializa/carrossel
    initSlider();
  };

  $.ajaxlight({
    sUrl: "./ashx/Consulta/ImagemConsulta.ashx",
    sType: "GET",
    fnSuccess: sucesso,
    fnBeforeSubmit: gInicio,
    bAsync: true,
  });
}

/* Slider/controle centralizado */
let timer = null;
let counter = 1;
let dots = [];
let slides = [];

function initSlider() {
  slides = Array.from(document.querySelectorAll(".myslide"));
  dots = Array.from(document.querySelectorAll(".dot"));

  if (!slides.length) return;

  // reinicia estado
  counter = 1;
  showSlide(counter);

  // init timer (5s padrão)
  resetTimer(5000);
}

function resetTimer(ms = 5000) {
  if (timer) clearInterval(timer);
  timer = setInterval(autoSlide, ms);
}

function autoSlide() {
  counter = (counter % slides.length) + 1;
  showSlide(counter);
}

function currentSlide(n) {
  counter = n;
  showSlide(counter);
  resetTimer();
}

function plusSlides(n) {
  counter = counter + n;
  showSlide(counter);
  resetTimer();
}

function showSlide(n) {
  if (!slides.length) return;

  // normaliza counter
  if (n > slides.length) counter = 1;
  if (n < 1) counter = slides.length;

  slides.forEach((s) => (s.style.display = "none"));
  slides[counter - 1].style.display = "block";

  if (dots.length) {
    dots.forEach((d) => (d.className = d.className.replace(" active", "")));
    if (dots[counter - 1]) dots[counter - 1].className += " active";
  }
}

